/**
 * Database connection configuration for postgres engine (DB).
 *
 * When DB_DATABASE_URL is set (e.g. in Docker), the URL is
 * used directly.  Otherwise individual host/port/username/password env vars
 * are required (local development).
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import type { MikroOrmModuleOptions } from '@mikro-orm/nestjs';
import { PostgreSqlDriver } from '@mikro-orm/postgresql';
import { ConfigService } from '@nestjs/config';

export function getDatabaseConfig(
  configService: ConfigService,
): MikroOrmModuleOptions {
  const databaseUrl = process.env['DB_DATABASE_URL'];
  const base: MikroOrmModuleOptions = {
    driver: PostgreSqlDriver,
    entities: [
      __dirname + '/../examples_order_service/entities/db/**/*.entity{.ts,.js}',
    ],
    allowGlobalContext: true,
    debug: configService.get<boolean>('DATABASE_LOGGING', false),
    pool: {
      max: 20,
    },
    migrations: {
      path: __dirname + '/../migrations/db',
      emit: 'ts',
    },
  };

  if (databaseUrl) {
    return {
      ...base,
      clientUrl: databaseUrl,
    };
  }

  return {
    ...base,
    host: 'localhost',
    port: 5432,
    user: (() => {
      const k = 'DB_DB_USER';
      if (!process.env[k]) {
        throw new Error(`${k} environment variable is required`);
      }
      return process.env[k] as string;
    })(),
    password: (() => {
      const k = 'DB_DB_PASSWORD';
      if (!process.env[k]) {
        throw new Error(`${k} environment variable is required`);
      }
      return process.env[k] as string;
    })(),
    dbName: 'db',
  };
}
